package com.Labprograms.operators;

public class RelationalOperators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		float a = 10.34f;
		float b = 30.56f;
		System.out.println("using == " + (a == b));
		System.out.println("using != " + (a != b));
		System.out.println("using > " + (a > b));
		System.out.println("using < " + (a < b));
		System.out.println("using >= " + (a >= b));
		System.out.println("using <= " + (a <= b));

	}
}
